"""Publish compiler-generated smali only as a UN1CA patch."""
from pathlib import Path
import datetime
import shutil
import sys

root = Path(__file__).resolve().parent.parent
output = root / 'smali/system/priv-app/SecSettings/SecSettings.apk/0011-Add-keybox-sources-and-revocation-submenu.patch'
parts = ['From: UN1CA <unica@local>\nSubject: [PATCH] Add keybox sources and revocation submenu\n\n'
         'Generated by settings/keybox/build.sh. Repository protocol: Duck-ToolBox / Tricky Addon.\n\n']
for source in sorted(Path(sys.argv[1]).rglob('*.smali')):
    if 'io/mesalabs/unica/keybox/' not in source.as_posix():
        continue  # Shared D8 annotations already supplied by the Quick Tiles patch.
    path = 'smali_classes4/' + source.relative_to(sys.argv[1]).as_posix()
    lines = source.read_text().splitlines(keepends=True)
    parts.append(f'diff --git a/{path} b/{path}\nnew file mode 100644\n--- /dev/null\n+++ b/{path}\n@@ -0,0 +1,{len(lines)} @@\n')
    parts.extend('+' + line for line in lines)
    parts.append('\n')
content = ''.join(parts)
if output.exists() and output.read_text() != content:
    shutil.copy2(output, str(output) + '.bak.' + datetime.datetime.now().strftime('%Y%m%d_%H%M%S_%f'))
output.write_text(content)
print(output)
